import Combine
import Foundation

/// Native implementation of HybridNitroFoldDuoProtocol.
/// This file is yours to edit — the protocol is generated by `nitrogen generate`.
public class NitroFoldDuoImpl: NSObject, HybridNitroFoldDuoProtocol {

    private let box = DuoStateBox()

    public override init() {
        super.init()
        let box = self.box
        Task { @MainActor in
            DuoFoldWatcher.shared = DuoFoldWatcher(box: box)
        }
    }


    public func currentState() -> DuoState {
        return box.current
    }

    public var stateChanges: AnyPublisher<DuoState, Never> {
        return box.subject.eraseToAnyPublisher()
    }

    public func updateGlassCapsule(
        viewId: Int64, symbols: [String], titles: [String], selectedIndex: Int64,
        tint: Int64, isDark: Bool
    ) {
        // Called from Dart's UI isolate; UIKit is main-thread only.
        Task { @MainActor in
            DuoGlassCapsuleRegistry.apply(
                id: viewId, symbols: symbols, titles: titles,
                selectedIndex: Int(selectedIndex), tint: Int(tint), isDark: isDark)
        }
    }

    public func updateGlassSurface(
        viewId: Int64, cornerRadius: Double, tint: Int64, isDark: Bool
    ) {
        Task { @MainActor in
            DuoGlassSurfaceRegistry.apply(
                id: viewId, cornerRadius: cornerRadius, tint: Int(tint),
                isDark: isDark)
        }
    }

    public func setGlassCapsuleMenu(
        viewId: Int64, buttonIndex: Int64, titles: [String], symbols: [String]
    ) {
        Task { @MainActor in
            DuoGlassCapsuleRegistry.setMenu(
                id: viewId, buttonIndex: Int(buttonIndex), titles: titles,
                symbols: symbols)
        }
    }

    public var glassCapsulePresses: AnyPublisher<DuoBarPress, Never> {
        return DuoCapsuleBus.shared.presses.eraseToAnyPublisher()
    }
}
